/*---
description: Uppercasing Latin-1 y with diaeresis leaves the one-byte range.
features: [ts-unicode-case-mapping, ts-strings, ts-unicode-sequences, ts-arrays, ts-tuples, ts-iteration]
---*/
// Generated by tooling/unicode-cases/case-mapping.ts; Unicode 17.0 / ICU 78.3.
// Contract: docs/foundations/unicode.md, Staying identical to node.
const examples: [string, string, string][] = [
  ["\u00FF", "\u00FF", "\u0178"],
  ["\u0061\u00FF\u007A", "\u0061\u00FF\u007A", "\u0041\u0178\u005A"],
];
for (const [input, lower, upper] of examples) {
  const lowered = input.toLowerCase();
  const uppered = input.toUpperCase();
  assert.sameValue(lowered, lower, "lowercase text");
  assert.sameValue(lowered.length, lower.length, "lowercase UTF-16 length");
  assert.sameValue(uppered, upper, "uppercase text");
  assert.sameValue(uppered.length, upper.length, "uppercase UTF-16 length");
}
